import {polynomialRoots,clamp,signCycle,entropyOf} from './math.js';
function rand(seed){let x=Math.sin(seed*999.123)*43758.5453;return x-Math.floor(x)}
export class AttractorSystem{
 constructor(count=9000,dim=8){this.count=count;this.dim=dim;this.t=0;this.seed=Math.random()*1e4;this.metrics={};this.reset(dim)}
 reset(dim=this.dim){this.dim=dim;this.pos=new Float32Array(this.count*dim);this.vel=new Float32Array(this.count*dim);for(let i=0;i<this.count;i++)for(let d=0;d<dim;d++){const q=rand(this.seed+i*17.1+d*3.7);this.pos[i*dim+d]=(q*2-1)*(.3+.7*rand(this.seed+d+i));this.vel[i*dim+d]=0}}
 step(p,dt=.016){const dim=this.dim, roots=polynomialRoots(p.degree,this.t,p.phi,p.rootPhase), n=this.count;let flux=0,curl=0,div=0,energy=0;const cycleSign=signCycle(Math.floor(this.t*p.cycleRate),p.binaryCycle);for(let i=0;i<n;i++){const off=i*dim,x0=this.pos[off],x1=this.pos[off+1]||0,root=roots[i%roots.length],dx=root[0]-x0,dy=root[1]-x1,rr=Math.sqrt(dx*dx+dy*dy+1e-4),rootForce=p.rootPower/(.2+rr),lens=p.lensMass/(.15+x0*x0+x1*x1),tx=-dy*p.coil,ty=dx*p.coil;let sum=0;for(let d=0;d<dim;d++)sum+=this.pos[off+d];for(let d=0;d<dim;d++){const next=this.pos[off+((d+1)%dim)],prev=this.pos[off+((d+dim-1)%dim)],noise=(rand(this.seed+i*13.77+d*91.3+Math.floor(this.t*60))-.5)*p.stochasticity,ode=(next-prev)*.15+sum*.015,imagFlip=(d%2===0?1:cycleSign);let f=ode*p.functor*imagFlip+noise;if(d===0)f+=dx*rootForce+tx*.25+x0*lens*.002;if(d===1)f+=dy*rootForce+ty*.25+x1*lens*.002;if(d===2)f+=Math.sin(this.t+x0*3)*.05*p.amplification;if(d===3)f+=Math.cos(this.t*.7+x1*3)*.05*p.amplification;this.vel[off+d]=this.vel[off+d]*p.damping+f*dt;this.pos[off+d]+=this.vel[off+d]*dt*p.speed;this.pos[off+d]=clamp(this.pos[off+d],-3.5,3.5)}flux+=lens/n;curl+=Math.abs(tx-ty)/n;div+=Math.abs(dx+dy)/n;energy+=rr/n}this.t+=dt*p.timeScale;this.metrics={flux,curl,div,energy,entropy:entropyOf([flux,curl,div,energy,p.stochasticity,p.functor]),roots:roots.length,dim};return roots}
}
